#!/usr/bin/env node

/**
 * Validate and normalize summary JSON generated by agent.
 *
 * Usage:
 * node scripts/validate-summary.js \
 *   --input tmp/summary-raw.json \
 *   --fetchFile tmp/fetch.json \
 *   --outFile tmp/summary.json
 */

const fs = require('fs');
const path = require('path');
const { extractJson, ensureSummaryShape } = require('./summary-utils');

function parseArgs(argv) {
  const args = {};
  for (let i = 2; i < argv.length; i += 1) {
    const token = argv[i];
    if (!token.startsWith('--')) continue;
    const key = token.slice(2);
    const next = argv[i + 1];
    if (!next || next.startsWith('--')) {
      args[key] = true;
      continue;
    }
    args[key] = next;
    i += 1;
  }
  return args;
}

function ensureValue(value, name) {
  if (value === undefined || value === null || value === '') {
    throw new Error(`Missing required value: ${name}`);
  }
}

function readJsonFile(filePath) {
  const raw = fs.readFileSync(filePath, 'utf8');
  return JSON.parse(raw);
}

function parseInputText(rawText) {
  const parsed = extractJson(rawText);
  if (!parsed) {
    throw new Error('Input does not contain valid JSON object');
  }
  return parsed;
}

function writeOutput(data, outFile) {
  const text = `${JSON.stringify(data, null, 2)}\n`;
  if (!outFile) {
    process.stdout.write(text);
    return;
  }
  fs.mkdirSync(path.dirname(outFile), { recursive: true });
  fs.writeFileSync(outFile, text);
}

function run() {
  const args = parseArgs(process.argv);
  ensureValue(args.input, 'input');
  ensureValue(args.fetchFile, 'fetchFile');

  const inputFile = path.resolve(args.input);
  const fetchFile = path.resolve(args.fetchFile);
  const outFile = args.outFile ? path.resolve(args.outFile) : null;

  const rawSummaryText = fs.readFileSync(inputFile, 'utf8');
  const summaryInput = parseInputText(rawSummaryText);
  const fetchData = readJsonFile(fetchFile);
  const normalized = ensureSummaryShape(summaryInput, fetchData);
  writeOutput(normalized, outFile);
}

try {
  run();
} catch (error) {
  process.stderr.write(`${String(error.message || error)}\n`);
  process.exit(1);
}
